export function SummaryLayout({ title, description, children }) {
  return (
    <div className="summary-layout">
      <header>
        <h1>{title}</h1>
        <p>{description}</p>
      </header>
      <div className="summary-grid">{children}</div>
    </div>
  )
}

.summary-layout {
  max-width: 1200px;
  margin: 0 auto;
  padding: 2rem;
}

.summary-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.25rem;
}

.summary-tile {
  background: var(--ax-bg-subtle);
  border: 1px solid var(--ax-border-neutral-subtle);
  border-radius: 16px;
  padding: 1.5rem;
  box-shadow: 0 12px 32px rgba(0,0,0,0.12);
}

.summary-tile ul {
  max-height: 200px;
  overflow: auto;
  padding-inline-start: 1.5rem;
}
